print('pid_ns baseline->active->after cores and active percent change')
for pid in sorted(set(out['baseline'].index)|set(out['active'].index)|set(out['after'].index)):
 b=out['baseline'].get(pid,0); i=out['active'].get(pid,0); aft=out['after'].get(pid,0)
 if max(b,i,aft)>.05:
  print(pid,round(b,3),round(i,3),round(aft,3),'pct',round((i/b-1)*100,1) if b else 'new')
","why":"Summarize matched-window per-container core rates and distinguish the entrant’s spike from changes among pre-existing containers."}

