function.arguments:
{"code":"# Summarize 20-second windows for CPU and mechanism counts; retain container attribution.
df2=df.copy(); df2['win']=((df2.bucket_start_s-secs('08:12:53'))//20).astype(int)
for e in ['sched_stat_runtime','block_rq_issue','block_rq_complete','net_dev_xmit','net_if_receive_skb','syscall_entry_futex','sched_wakeup']:
 z=df2[df2.event==e].groupby(['win','procname','pid_ns']).n.sum().reset_index()
 print('\nEVENT',e)
 for w,g in z.groupby('win'):
  top=g.sort_values('n',ascending=False).head(3)
  print(hms(secs('08:12:53')+w*20), 'total',int(g.n.sum()), 'top',[(r.procname,str(r.pid_ns),int(r.n)) for r in top.itertuples(index=False)])","why":"Locate any sustained mechanism shift and its container actors, comparing each candidate interval with neighboring periods."}

