windows=[('quiet','08:14:15','08:14:45'),('pre_spike','08:13:13','08:13:43'),('spike','08:13:53','08:14:08'),('high','08:16:08','08:16:38'),('late','08:16:38','08:16:56')]; ev=['sched_switch','sched_wakeup','block_rq_issue','net_dev_xmit'];
for label,a,b in windows:
 x=df[(df.bucket_start_s>=secs(a))&(df.bucket_start_s<secs(b))]; print('\n',label,a,b,'duration',secs(b)-secs(a)); print(x[x.event.isin(ev)].groupby('event').n.sum().div(secs(b)-secs(a)).round(1).to_dict()); print('top sched switch process/container',x[x.event=='sched_switch'].groupby(['procname','pid_ns']).n.sum().sort_values(ascending=False).head(8).to_dict())

